exploreUrl:
@js:
var sort = [],
push = (title, link, size) => 
sort.push({
    "title": title,
    "url": link,
    "style": {
      "layout_flexGrow": 1,
      "layout_flexBasisPercent": size
    }
  });

var su = source.key,
url = su + "/menu.html",
html = java.ajax(url),
j = org.jsoup.Jsoup.parse(html),
a = j.select('.divmen a');

Array.from(a, (x, i) => {
    if(i != 0 && i != 4 && i != 5){
        var name = x.text(),
        href = x.attr("href");
        push(name, href, 0.25);
    }
});

JSON.stringify(sort);
